import json
import os
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs

books = {}  # id -> book dict
next_id = 1


class BookHandler(BaseHTTPRequestHandler):

    def _send_json(self, code, body=None):
        data = b"" if body is None else json.dumps(body).encode()
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        if data:
            self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        if data:
            self.wfile.write(data)

    def _read_body(self):
        length = int(self.headers.get("Content-Length", 0))
        raw = self.rfile.read(length) if length else b""
        return raw

    def _parse_json_body(self):
        raw = self._read_body()
        try:
            obj = json.loads(raw)
        except (json.JSONDecodeError, ValueError):
            return None
        if not isinstance(obj, dict):
            return None
        return obj

    def _validate_book_fields(self, data):
        """Validate and extract book fields. Returns (book_dict, error_msg)."""
        for field in ("title", "author", "isbn"):
            val = data.get(field)
            if not isinstance(val, str) or val == "":
                return None, f"{field} is required and must be a non-empty string"
        synopsis = data.get("synopsis", "")
        if not isinstance(synopsis, str):
            return None, "synopsis must be a string"
        return {"title": val, "author": data["author"], "isbn": data["isbn"],
                "synopsis": synopsis}, None

    def _handle_books_collection(self, method):
        if method == "GET":
            self._list_books()
        elif method == "POST":
            self._create_book()
        else:
            self._send_json(405, {"error": "Method not allowed"})

    def _handle_single_book(self, book_id):
        if isinstance(book_id, int):
            method = self.command
            if method == "GET":
                self._get_book(book_id)
            elif method == "PUT":
                self._update_book(book_id)
            elif method == "DELETE":
                self._delete_book(book_id)
            else:
                self._send_json(405, {"error": "Method not allowed"})
        else:
            self._send_json(400, {"error": f"Invalid id '{book_id}', must be an integer"})

    def _list_books(self):
        result = list(books.values())
        parsed = urlparse(self.path)
        qs = parse_qs(parsed.query)
        params_used = set()

        # Check for unknown query parameters
        known_params = {"id", "title", "author", "isbn", "synopsis", "q"}
        for key in qs:
            if key not in known_params:
                self._send_json(400, {"error": f"Unknown query parameter: {key}"})
                return

        # Filter by id (numeric)
        if "id" in qs:
            try:
                target_id = int(qs["id"][0])
                result = [b for b in result if b["id"] == target_id]
            except ValueError:
                self._send_json(400, {"error": "id query parameter must be an integer"})
                return

        # Filter by fields (case-insensitive contains)
        text_params = ("title", "author", "isbn", "synopsis")
        for field in text_params:
            if field in qs:
                val = qs[field][0].lower()
                result = [b for b in result if val in b[field].lower()]

        # Filter by q (searches all text fields)
        if "q" in qs:
            val = qs["q"][0].lower()
            result = [b for b in result if any(val in b[f].lower() for f in text_params)]

        self._send_json(200, result)

    def _create_book(self):
        data = self._parse_json_body()
        if data is None:
            self._send_json(400, {"error": "Request body must be a JSON object"})
            return
        if "id" in data:
            self._send_json(400, {"error": "id must not be provided in request body"})
            return
        book, err = self._validate_book_fields(data)
        if err:
            self._send_json(400, {"error": err})
            return
        global next_id
        book["id"] = next_id
        next_id += 1
        books[book["id"]] = book
        self._send_json(201, book)

    def _get_book(self, book_id):
        book = books.get(book_id)
        if book is None:
            self._send_json(404, {"error": f"Book with id {book_id} not found"})
            return
        self._send_json(200, book)

    def _update_book(self, book_id):
        book = books.get(book_id)
        if book is None:
            self._send_json(404, {"error": f"Book with id {book_id} not found"})
            return
        data = self._parse_json_body()
        if data is None:
            self._send_json(400, {"error": "Request body must be a JSON object"})
            return
        book["title"], err = self._validate_field(data.get("title"), "title")
        if err:
            self._send_json(400, {"error": err})
            return
        book["author"], err = self._validate_field(data.get("author"), "author")
        if err:
            self._send_json(400, {"error": err})
            return
        book["isbn"], err = self._validate_field(data.get("isbn"), "isbn")
        if err:
            self._send_json(400, {"error": err})
            return
        synopsis, err = self._validate_optional_str(data.get("synopsis"))
        if err:
            self._send_json(400, {"error": err})
            return
        book["synopsis"] = synopsis
        self._send_json(200, dict(book))

    def _delete_book(self, book_id):
        if book_id not in books:
            self._send_json(404, {"error": f"Book with id {book_id} not found"})
            return
        del books[book_id]
        self._send_json(204)

    def _validate_field(self, val, field_name):
        if not isinstance(val, str) or val == "":
            return None, f"{field_name} is required and must be a non-empty string"
        return val, None

    def _validate_optional_str(self, val):
        if val is not None and not isinstance(val, str):
            return None, "synopsis must be a string"
        return val if val is not None else "", None

    def do_GET(self):
        parsed = urlparse(self.path)
        path = parsed.path.rstrip("/") or "/"
        parts = path.split("/")
        if len(parts) == 2 and parts[1] == "books":
            self._handle_books_collection("GET")
        elif len(parts) == 3 and parts[1] == "books":
            try:
                book_id = int(parts[2])
            except ValueError:
                book_id = parts[2]
            self._handle_single_book(book_id)
        else:
            self._send_json(404, {"error": "Not found"})

    def do_POST(self):
        parsed = urlparse(self.path)
        path = parsed.path.rstrip("/") or "/"
        if len(path.split("/")) == 2 and path.split("/")[1] == "books":
            self._handle_books_collection("POST")
        else:
            self._send_json(404, {"error": "Not found"})

    def do_PUT(self):
        parsed = urlparse(self.path)
        path = parsed.path.rstrip("/") or "/"
        parts = path.split("/")
        if len(parts) == 3 and parts[1] == "books":
            try:
                book_id = int(parts[2])
            except ValueError:
                book_id = parts[2]
            self._handle_single_book(book_id)
        else:
            self._send_json(404, {"error": "Not found"})

    def do_DELETE(self):
        parsed = urlparse(self.path)
        path = parsed.path.rstrip("/") or "/"
        parts = path.split("/")
        if len(parts) == 3 and parts[1] == "books":
            try:
                book_id = int(parts[2])
            except ValueError:
                book_id = parts[2]
            self._handle_single_book(book_id)
        else:
            self._send_json(404, {"error": "Not found"})

    def log_message(self, format, *args):
        pass  # suppress logs


if __name__ == "__main__":
    port = int(os.environ.get("PORT", 8000))
    server = HTTPServer(("127.0.0.1", port), BookHandler)
    print(f"Server running on http://127.0.0.1:{port}")
    server.serve_forever()
